(function() {
    'use strict';

    class EcommerceAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'E-Commerce Launch Playbook';
            this.version = '1.1.0';

            this.FULFILLMENT_MODELS = {
                self:     { costPerOrder: 4.00, convBonus: 0,      brandBonus: 0.5 },
                threePL:  { costPerOrder: 6.50, convBonus: 0.005,  brandBonus: 1.0 },
                dropship: { costPerOrder: 2.00, convBonus: -0.005, brandBonus: -0.5 }
            };

            this.PHASES = [
                { months: [1, 2],  id: 'launch',   en: 'Phase 1: Launch',   es: 'Fase 1: Lanzamiento' },
                { months: [3, 4, 5], id: 'optimize', en: 'Phase 2: Optimize', es: 'Fase 2: Optimizar' },
                { months: [6, 7, 8, 9], id: 'scale', en: 'Phase 3: Scale',   es: 'Fase 3: Escalar' },
                { months: [10, 11, 12], id: 'sustain', en: 'Phase 4: Sustain', es: 'Fase 4: Sostener' }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 15000,
                    audiencePool: 0,
                    emailList: 0,
                    brandEquity: 20,
                    nps: 50,
                    totalRevenue: 0,
                    totalProfit: 0,
                    totalCustomers: 0,
                    repeatRate: 0.05,
                    cpmMultiplier: 1,
                    cogsMultiplier: 1,
                    convMultiplier: 1,
                    chargebackRate: 0,
                    cashHistory: [],
                    revenueHistory: [],
                    profitHistory: [],
                    ltvCacHistory: [],
                    cacHistory: [],
                    cohorts: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    marketingBudget: 2000,
                    tofuPct: 40,
                    bofuPct: 30,
                    price: 45,
                    fulfillment: 'threePL'
                };
            }
            this._updateBriefing(state);
            this._attachFunnelListeners();
        }

        _attachFunnelListeners() {
            var tofuEl = document.getElementById('tofuInput');
            var bofuEl = document.getElementById('bofuInput');
            var mofuEl = document.getElementById('mofuDisplay');
            if (tofuEl && bofuEl && mofuEl) {
                var update = function() {
                    var t = parseInt(tofuEl.value) || 0;
                    var b = parseInt(bofuEl.value) || 0;
                    var m = Math.max(0, 100 - t - b);
                    mofuEl.textContent = m + '%';
                };
                tofuEl.addEventListener('input', update);
                bofuEl.addEventListener('input', update);
                update();
            }
        }

        _getPhase(month) {
            for (var i = 0; i < this.PHASES.length; i++) {
                if (this.PHASES[i].months.indexOf(month) !== -1) return this.PHASES[i];
            }
            return this.PHASES[3];
        }

        _updateBriefing(state) {
            var month = state.currentPeriod || 1;
            var phase = this._getPhase(month);

            var badgeEl = document.getElementById('phaseBadge');
            if (badgeEl) badgeEl.textContent = phase.en;

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = window.mySimulation ? window.mySimulation.t('brief_' + phase.id) : '';

            var eventBanner = document.getElementById('eventBanner');
            if (eventBanner) {
                var evtMsg = this._getEventPreview(month);
                if (evtMsg) {
                    eventBanner.style.display = 'block';
                    var iconEl = document.getElementById('eventIcon');
                    var textEl = document.getElementById('eventText');
                    if (iconEl) iconEl.textContent = evtMsg.icon;
                    if (textEl) textEl.innerHTML = evtMsg.text;
                } else {
                    eventBanner.style.display = 'none';
                }
            }
        }

        _getEventPreview(month) {
            if (!window.mySimulation) return null;
            if (month === 3) return { icon: '\uD83D\uDD25', text: window.mySimulation.t('event_viral') };
            if (month === 6) return { icon: '\uD83D\uDEA2', text: window.mySimulation.t('event_supplier') };
            if (month === 7) return { icon: '\uD83D\uDEA8', text: window.mySimulation.t('event_fraud') };
            if (month === 8) return { icon: '\u2B50', text: window.mySimulation.t('event_badreviews') };
            if (month === 10) return { icon: '\uD83C\uDFAF', text: window.mySimulation.t('event_competitor') };
            if (month === 11) return { icon: '\uD83D\uDD12', text: window.mySimulation.t('event_ios') };
            return null;
        }

        _applyEvents(ds, month) {
            ds.cpmMultiplier = 1;
            ds.cogsMultiplier = 1;
            ds.convMultiplier = 1;
            ds.chargebackRate = 0;

            if (month === 3) {
                ds.convMultiplier = 2.5;
            } else if (month === 6) {
                ds.cogsMultiplier = 1.35;
            } else if (month === 7) {
                ds.chargebackRate = 0.03;
            } else if (month === 8) {
                ds.convMultiplier = 0.7;
                ds.nps = Math.max(20, ds.nps - 15);
            } else if (month === 10) {
                ds.cpmMultiplier = 1.6;
            } else if (month === 11) {
                ds.cpmMultiplier = 1.3;
            }
        }

        validateDecisions(decisions) {
            var budgetEl = document.getElementById('budgetInput');
            if (budgetEl) decisions.marketingBudget = parseFloat(budgetEl.value);

            var tofuEl = document.getElementById('tofuInput');
            if (tofuEl) decisions.tofuPct = parseInt(tofuEl.value);

            var bofuEl = document.getElementById('bofuInput');
            if (bofuEl) decisions.bofuPct = parseInt(bofuEl.value);

            var priceEl = document.getElementById('priceInput');
            if (priceEl) decisions.price = parseFloat(priceEl.value);

            var fulfillEl = document.getElementById('fulfillmentSelect');
            if (fulfillEl) decisions.fulfillment = fulfillEl.value;

            if (isNaN(decisions.marketingBudget) || decisions.marketingBudget < 0) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_warning'), 'warning');
                return false;
            }

            var cash = window.mySimulation.state.domainState.cash;
            if (decisions.marketingBudget > Math.max(0, cash)) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_exceed'), 'warning');
                return false;
            }

            var tofu = decisions.tofuPct || 0;
            var bofu = decisions.bofuPct || 0;
            if (tofu + bofu > 100 || tofu < 0 || bofu < 0) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('alloc_warning'), 'warning');
                return false;
            }

            if (!decisions.price || decisions.price < 10 || decisions.price > 200) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('price_warning'), 'warning');
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var month = state.currentPeriod;

            this._applyEvents(ds, month);

            var tofuPct = (d.tofuPct || 0) / 100;
            var bofuPct = (d.bofuPct || 0) / 100;
            var mofuPct = Math.max(0, 1 - tofuPct - bofuPct);

            var tofuBudget = d.marketingBudget * tofuPct;
            var bofuBudget = d.marketingBudget * bofuPct;
            var mofuBudget = d.marketingBudget * mofuPct;

            var cpm = 8 * ds.cpmMultiplier;
            var tofuImpressions = (tofuBudget / Math.max(cpm, 0.01)) * 1000;
            var tofuClicks = tofuImpressions * 0.012;
            var tofuConversions = Math.round(tofuClicks * 0.008 * ds.convMultiplier);
            ds.audiencePool += Math.round(tofuClicks * 0.3);

            var mofuReach = Math.min(mofuBudget / 1.5, ds.audiencePool * 0.1);
            var mofuConversions = Math.round(mofuReach * 0.025 * ds.convMultiplier);

            var marketVol = 5000;
            var bofuReach = Math.min(bofuBudget / 3, marketVol * 0.4);
            var brandQualityBonus = ds.brandEquity / 500;
            var bofuConversions = Math.round(bofuReach * (0.04 + brandQualityBonus) * ds.convMultiplier);

            var emailConversions = Math.round(ds.emailList * 0.003);
            var organicConversions = Math.round(ds.brandEquity * 0.15);

            var newCustomers = Math.max(0, tofuConversions + mofuConversions + bofuConversions + emailConversions + organicConversions);

            var repeatCustomers = 0;
            for (var i = 0; i < ds.cohorts.length; i++) {
                var c = ds.cohorts[i];
                var age = month - c.month;
                if (age > 0) {
                    repeatCustomers += Math.round(c.size * ds.repeatRate * Math.pow(0.7, age));
                }
            }

            var totalOrders = newCustomers + repeatCustomers;
            var revenue = totalOrders * d.price;

            var cogsRate = 0.45 * ds.cogsMultiplier;
            var cogs = revenue * cogsRate;

            var fm = this.FULFILLMENT_MODELS[d.fulfillment] || this.FULFILLMENT_MODELS.threePL;
            var fulfillCost = totalOrders * fm.costPerOrder;
            var chargebacks = revenue * ds.chargebackRate;
            var platformFees = revenue * 0.035;
            var totalCosts = cogs + fulfillCost + d.marketingBudget + chargebacks + platformFees;
            var profit = revenue - totalCosts;

            var cac = newCustomers > 0 ? d.marketingBudget / newCustomers : 0;
            var grossMargin = Math.max(0, 1 - cogsRate - (fm.costPerOrder / Math.max(d.price, 1)) - 0.035);
            var ltv = d.price * grossMargin * (1 + ds.repeatRate * 3);
            var ltvCac = cac > 0 ? Math.round((ltv / cac) * 100) / 100 : 0;

            ds.cash += profit;

            if (ds.cash < 0) {
                var loanPenalty = Math.abs(ds.cash) * 0.2;
                ds.cash -= loanPenalty;
            }

            ds.totalRevenue += revenue;
            ds.totalProfit += profit;
            ds.totalCustomers += newCustomers;

            ds.brandEquity += fm.brandBonus;
            if (profit > 0) ds.brandEquity += 0.5;
            if (ds.nps > 60) ds.brandEquity += 1;
            if (ds.nps < 40) ds.brandEquity -= 0.5;
            ds.brandEquity = Math.max(0, Math.min(100, ds.brandEquity));

            ds.repeatRate = Math.min(0.40, ds.repeatRate + 0.008 * (ds.brandEquity / 50));
            ds.nps = Math.min(100, ds.nps + (profit > 0 ? 1 : -2));
            ds.emailList += Math.round(newCustomers * 0.6);

            if (newCustomers > 0) {
                ds.cohorts.push({ month: month, size: newCustomers });
            }

            ds.cashHistory.push(Math.round(ds.cash));
            ds.revenueHistory.push(Math.round(revenue));
            ds.profitHistory.push(Math.round(profit));
            ds.ltvCacHistory.push(ltvCac);
            ds.cacHistory.push(Math.round(cac));

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: month,
                newCustomers: newCustomers,
                repeatCustomers: repeatCustomers,
                totalOrders: totalOrders,
                revenue: Math.round(revenue),
                profit: Math.round(profit),
                cac: Math.round(cac),
                ltv: Math.round(ltv),
                ltvCac: ltvCac,
                cash: Math.round(ds.cash),
                brandEquity: Math.round(ds.brandEquity)
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash',
                function(v) { return '$' + Math.round(v).toLocaleString(); });
            uiManager.bind('revenueDisplay', 'domainState.totalRevenue',
                function(v) { return '$' + Math.round(v).toLocaleString(); });
            uiManager.bind('customersDisplay', 'domainState.totalCustomers',
                function(v) { return v.toLocaleString(); });
            uiManager.bind('cacDisplay', 'results.cac',
                function(v) { return '$' + (v || 0); });
            uiManager.bind('ltvCacDisplay', 'results.ltvCac',
                function(v) { return (v || 0).toFixed(1) + ':1'; });
            uiManager.bind('brandDisplay', 'domainState.brandEquity',
                function(v) { return Math.round(v) + '/100'; });
        }

        getChartConfig() {
            return {
                cashChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Cash Balance ($)',
                                data: [],
                                borderColor: '#27ae60',
                                backgroundColor: 'rgba(39,174,96,0.1)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.2
                            },
                            {
                                label: 'Monthly Revenue ($)',
                                data: [],
                                borderColor: '#2980b9',
                                backgroundColor: 'rgba(41,128,185,0.08)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: 'Cash & Revenue Over Time' } },
                        scales: { y: { beginAtZero: false } }
                    }
                },
                ltvCacChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'LTV:CAC Ratio',
                                data: [],
                                borderColor: '#e74c3c',
                                backgroundColor: 'rgba(231,76,60,0.1)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.2
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'LTV : CAC Ratio (Target: 3:1)' },
                            annotation: {}
                        },
                        scales: {
                            y: { beginAtZero: true, suggestedMax: 6 }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.cashHistory.map(function(_, i) { return 'M' + (i + 1); });
            return {
                cashChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.cashHistory },
                        { data: state.domainState.revenueHistory }
                    ]
                },
                ltvCacChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.ltvCacHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var profits = history.map(function(r) { return r.results ? r.results.profit || 0 : 0; });
            var totalProfit = profits.reduce(function(s, p) { return s + p; }, 0);
            var avgProfit = totalProfit / profits.length;

            var lastRecord = history[history.length - 1];
            var finalCash = lastRecord.results ? lastRecord.results.cash || 0 : 0;
            var finalLtvCac = lastRecord.results ? lastRecord.results.ltvCac || 0 : 0;
            var finalBrand = lastRecord.results ? lastRecord.results.brandEquity || 0 : 0;

            var netMarginPct = 0;
            var totalRev = history.reduce(function(s, r) { return s + (r.results ? r.results.revenue || 0 : 0); }, 0);
            if (totalRev > 0) netMarginPct = Math.round((totalProfit / totalRev) * 100);

            var score = 0;
            score += Math.min(30, Math.max(0, netMarginPct) * 1.5);
            score += Math.min(25, finalLtvCac * 5);
            score += Math.min(20, Math.max(0, totalProfit / 500));
            score += Math.min(15, finalBrand * 0.15);
            score += Math.min(10, Math.max(0, finalCash / 1500));
            score = Math.round(score);

            if (finalCash < 0) score = Math.max(0, score - 20);

            var performance = 'Needs Improvement';
            if (score >= 40) performance = 'Good';
            if (score >= 60) performance = 'Very Good';
            if (score >= 80) performance = 'Excellent';

            var insights = [];
            if (finalLtvCac >= 3) {
                insights.push('Strong LTV:CAC ratio - sustainable growth engine achieved.');
            } else {
                insights.push('LTV:CAC below 3:1 target. Focus on retention or reduce acquisition cost.');
            }
            if (netMarginPct < 0) {
                insights.push('Negative net margin. Unit economics were not proven before scaling.');
            }
            if (finalBrand >= 60) {
                insights.push('Excellent brand equity built. Long-term competitive moat established.');
            }

            return {
                eurekaScore: score,
                totalProfit: totalProfit,
                netMarginPct: netMarginPct,
                finalLtvCac: finalLtvCac,
                finalBrand: finalBrand,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.cash < 0) return window.mySimulation.t('hint_cash_negative');
            if (results.ltvCac > 0 && results.ltvCac < 1) return window.mySimulation.t('hint_ltvcac_bad');
            if (results.ltvCac >= 3) return window.mySimulation.t('hint_ltvcac_great');
            if (results.profit < 0) return window.mySimulation.t('hint_loss');
            if (results.newCustomers < 5) return window.mySimulation.t('hint_low_acq');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.revenue',       label: 'Revenue',    i18nKey: 'col_revenue',    formatter: function(v) { return '$' + (v || 0).toLocaleString(); } },
                { key: 'results.newCustomers',   label: 'New Cust.',  i18nKey: 'col_new_cust' },
                { key: 'results.repeatCustomers',label: 'Repeat',     i18nKey: 'col_repeat' },
